		if !math.IsPowerOf2(uint64(len(hashLayer))) {
			return nil, nil, errors.Errorf("hash layer is a non power of 2: %d", len(hashLayer))
		}
		hashLayer = htr.VectorizedSha256(hashLayer)
		layers[i] = hashLayer
		i++
	}
